import '../../../../../../Core/Models/product_model.dart';import '../../../../../../Core/Storage/Remote/api_endpoints.dart';import '../../../../../../Core/Storage/Remote/api_service.dart';import '../../../../App/Home/data/models/product_preview_entities.dart';class SearchSources {  static Future<List<ProductPreviewEntities>> searchProducts() async {      final response = await DioHelper.getData(        path: ApiEndpoints.product,      );      if (response.statusCode == 200 && response.data != null) {        final data = response.data["data"]["products"];        if (data is List) {          return data              .map((item) => ProductPreviewEntities.fromProduct(            ProductModel.fromJson(item),          ))              .toList();        } else {          return [];        }      } else {        return [];      }  }// Future<List<ProductPreviewEntities>> searchProductsByFilters()async{//   final response = await DioHelper.getData(//     path: ApiEndpoints.product,//   );//   return (response.data["data"] as List)//       .map(//         (item) => ProductPreviewEntities.fromJson(item),//       )//       .toList();// }}